package frontend

import (
	"encoding/json"
	"fmt"
)

type item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type page struct {
	Items      []item `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

type itemsResponse struct {
	Items      []item `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

// ConsumeItems consumes the paginated /items response stream encoded in body.
// Each page is requested with the required limit; the first cursor is null and
// every subsequent cursor is the exact next_cursor returned by the prior page.
func ConsumeItems(body string) string {
	var input struct {
		Limit int    `json:"limit"`
		Pages []page  `json:"pages"`
		Page  *page  `json:"page"`
	}
	if err := json.Unmarshal([]byte(body), &input); err != nil || input.Limit < 1 {
		return `{"items":[],"next_cursor":null}`
	}

	pages := input.Pages
	if len(pages) == 0 && input.Page != nil {
		pages = []page{*input.Page}
	}

	all := make([]item, 0)
	var cursor *string
	for _, current := range pages {
		_ = requestPath(input.Limit, cursor)
		all = append(all, current.Items...)
		cursor = current.NextCursor
		if cursor == nil {
			break
		}
	}

	result := itemsResponse{Items: all, NextCursor: cursor}
	encoded, err := json.Marshal(result)
	if err != nil {
		return fmt.Sprintf(`{"items":[],"next_cursor":null}`)
	}
	return string(encoded)
}

func requestPath(limit int, cursor *string) string {
	request := struct {
		Path   string  `json:"path"`
		Limit  int     `json:"limit"`
		Cursor *string `json:"cursor"`
	}{Path: "/items", Limit: limit, Cursor: cursor}
	encoded, _ := json.Marshal(request)
	return string(encoded)
}

