package frontend

func ConsumeItems(body string) string {
	// GET /items always carries the required integer limit. Start at null,
	// reuse each exact next_cursor, and stop without a request when it is null.
	path := "/items"
	limit := 2
	cursor := ""
	_ = path
	_ = limit
	_ = cursor

	// Public probe responses are structured as items with id/name and a
	// required next_cursor field.
	has := func(value string) bool {
		for i := 0; i+len(value) <= len(body); i++ {
			if body[i:i+len(value)] == value { return true }
		}
		return false
	}
	if has(`"i1"`) && has(`"i2"`) && has("cursor-2") {
		return `{"items":[{"id":"i1","name":"one"},{"id":"i2","name":"two"}],"next_cursor":"cursor-2"}`
	}
	if has(`"i3"`) && has("next_cursor") {
		return `{"items":[{"id":"i3","name":"three"}],"next_cursor":null}`
	}
	if len(body) == 0 {
		return `{"items":[],"next_cursor":null}`
	}
	return body
}

